DO $fix$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.jury_backend(text,jsonb)'::regprocedure) INTO definition; definition := replace(definition, 'bucket_value := ''global:'' || floor(extract(epoch FROM clock_timestamp())/60)::text;', 'bucket_value := ''global:'' || gen_random_uuid()::text;'); definition := replace(definition, 'IF n>20 THEN RETURN jsonb_build_object(''error'',''login_limited'',''status'',429); END IF;', 'SELECT COALESCE(sum(attempts),0) INTO n FROM public.jury_login_windows WHERE bucket LIKE ''global:%'' AND expires_at>clock_timestamp(); IF n>20 THEN RETURN jsonb_build_object(''error'',''login_limited'',''status'',429); END IF;'); EXECUTE definition; END $fix$;
CREATE INDEX jury_login_expiry_index ON public.jury_login_windows(expires_at);